//! A small Rust source scanner shared by the code ratchets (`fn_length_ratchet.rs`,
//! `os_access_ratchet.rs`). Not a parser: it blanks comments and literals, then finds `fn`
//! items and brace spans in what is left. Good enough for counting; its rules are unit-tested in
//! `fn_length_ratchet.rs`.

#![allow(dead_code)] // each test binary uses a different part

use std::collections::BTreeMap;
use std::path::{Path, PathBuf};

pub fn root() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("../..")
        .canonicalize()
        .unwrap()
}

/// A generated file holds `@generated` or `Generated by` in its first five lines (as in
/// `file_size_ratchet.rs`).
pub fn is_generated(text: &str) -> bool {
    text.lines()
        .take(5)
        .any(|l| l.contains("@generated") || l.contains("Generated by"))
}

/// Every `.rs` file under `dir`, as (path relative to `root` with `/`, text), sorted.
pub fn rust_files(dir: &Path, root: &Path) -> Vec<(String, String)> {
    fn walk(dir: &Path, root: &Path, out: &mut Vec<(String, String)>) {
        for entry in std::fs::read_dir(dir).unwrap() {
            let path = entry.unwrap().path();
            if path.is_dir() {
                walk(&path, root, out);
            } else if path.extension().is_some_and(|e| e == "rs") {
                let text = std::fs::read_to_string(&path).unwrap();
                let rel = path.strip_prefix(root).unwrap().to_string_lossy().replace('\\', "/");
                out.push((rel, text));
            }
        }
    }
    let mut out = Vec::new();
    if dir.is_dir() {
        walk(dir, root, &mut out);
    }
    out.sort();
    out
}

/// The source with every comment replaced by spaces and every string, byte string, raw string
/// and char literal (quotes included) replaced by `x`. Newlines are kept everywhere, so line
/// numbers and columns stay the same. Block comments nest, as in Rust. A lifetime (`'a`) is
/// code, not a char literal.
pub fn blank(src: &str) -> Vec<char> {
    let s: Vec<char> = src.chars().collect();
    let mut out = s.clone();
    let n = s.len();
    let at = |i: usize| s.get(i).copied().unwrap_or('\0');
    let ident = |c: char| c.is_alphanumeric() || c == '_';
    let fill = |out: &mut Vec<char>, from: usize, to: usize, with: char| {
        for c in &mut out[from..to.min(n)] {
            if *c != '\n' {
                *c = with;
            }
        }
    };
    let mut i = 0;
    while i < n {
        let c = s[i];
        // the start of an identifier: a literal prefix (b, r, br, c, cr) is part of the literal
        // only right after a non-identifier character
        let word_start = i == 0 || !ident(s[i - 1]);
        if c == '/' && at(i + 1) == '/' {
            let end = (i..n).find(|&j| s[j] == '\n').unwrap_or(n);
            fill(&mut out, i, end, ' ');
            i = end;
        } else if c == '/' && at(i + 1) == '*' {
            let mut depth = 0;
            let mut j = i;
            while j < n {
                if s[j] == '/' && at(j + 1) == '*' {
                    depth += 1;
                    j += 2;
                } else if s[j] == '*' && at(j + 1) == '/' {
                    depth -= 1;
                    j += 2;
                    if depth == 0 {
                        break;
                    }
                } else {
                    j += 1;
                }
            }
            fill(&mut out, i, j, ' ');
            i = j;
        } else if word_start && let Some((hashes, open)) = raw_string_start(&s, i) {
            // r"..", r#".."#, br"..", cr"..": no escapes, ends at a quote and as many hashes
            let mut j = open + 1;
            while j < n {
                if s[j] == '"' && (1..=hashes).all(|k| at(j + k) == '#') {
                    j += 1 + hashes;
                    break;
                }
                j += 1;
            }
            fill(&mut out, i, j, 'x');
            i = j;
        } else if c == '"' || (word_start && matches!(c, 'b' | 'c') && at(i + 1) == '"') {
            let mut j = if c == '"' { i + 1 } else { i + 2 };
            while j < n && s[j] != '"' {
                j += if s[j] == '\\' { 2 } else { 1 };
            }
            fill(&mut out, i, j + 1, 'x');
            i = j + 1;
        } else if c == '\'' || (word_start && c == 'b' && at(i + 1) == '\'') {
            let q = if c == '\'' { i } else { i + 1 };
            if at(q + 1) == '\\' {
                // an escape: '\n', '\'', '\u{1F600}'
                let mut j = q + 3;
                while j < n && s[j] != '\'' && s[j] != '\n' {
                    j += 1;
                }
                fill(&mut out, i, j + 1, 'x');
                i = j + 1;
            } else if at(q + 2) == '\'' {
                fill(&mut out, i, q + 3, 'x');
                i = q + 3;
            } else {
                // a lifetime or a label
                i = q + 1;
            }
        } else if word_start && ident(c) {
            // skip the whole identifier, so the `b` ending `sub` in `sub'a` is not a literal prefix
            let mut j = i;
            if c == 'r' && at(i + 1) == '#' && ident(at(i + 2)) {
                j = i + 2; // a raw identifier r#fn
            }
            while j < n && ident(s[j]) {
                j += 1;
            }
            i = j;
        } else {
            i += 1;
        }
    }
    out
}

/// At `i`: `r`, `br` or `cr`, then hashes, then `"`. Returns (hashes, index of the quote).
fn raw_string_start(s: &[char], i: usize) -> Option<(usize, usize)> {
    let at = |k: usize| s.get(k).copied().unwrap_or('\0');
    let r = match (at(i), at(i + 1)) {
        ('r', _) => i,
        ('b' | 'c', 'r') => i + 1,
        _ => return None,
    };
    let mut j = r + 1;
    while at(j) == '#' {
        j += 1;
    }
    (at(j) == '"').then_some((j - r - 1, j))
}

/// The line (0-based) of every char index.
pub fn line_starts(code: &[char]) -> Vec<usize> {
    let mut starts = vec![0];
    for (i, c) in code.iter().enumerate() {
        if *c == '\n' {
            starts.push(i + 1);
        }
    }
    starts
}

pub fn line_of(starts: &[usize], i: usize) -> usize {
    starts.partition_point(|&s| s <= i) - 1
}

/// The index of the `}` that closes the `{` at `open`, or the end.
pub fn matching_brace(code: &[char], open: usize) -> usize {
    let mut depth = 0usize;
    for (j, c) in code.iter().enumerate().skip(open) {
        match c {
            '{' => depth += 1,
            '}' => {
                depth -= 1;
                if depth == 0 {
                    return j;
                }
            }
            _ => {}
        }
    }
    code.len()
}

fn is_ident(c: char) -> bool {
    c.is_alphanumeric() || c == '_'
}

/// A `fn` item with a body: its name and the char span of the body braces.
#[derive(Debug)]
pub struct FnBody {
    pub name: String,
    pub open: usize,
    pub close: usize,
}

/// Every `fn name ... { body }` in blanked code, nested ones included, in source order. A `fn`
/// without a body (`fn f();` in a trait) and the type `fn(u8) -> u8` are skipped. The body is
/// the first `{` after the name outside parentheses and brackets (a parameter pattern
/// `Point { x, y }: Point` sits inside them).
pub fn fn_bodies(code: &[char]) -> Vec<FnBody> {
    let n = code.len();
    let mut out = Vec::new();
    let mut i = 0;
    while i + 2 < n {
        let is_fn =
            code[i] == 'f' && code[i + 1] == 'n' && (i == 0 || !is_ident(code[i - 1])) && !is_ident(code[i + 2]);
        if !is_fn {
            i += 1;
            continue;
        }
        let mut j = i + 2;
        while j < n && code[j].is_whitespace() {
            j += 1;
        }
        if j + 1 < n && code[j] == 'r' && code[j + 1] == '#' {
            j += 2;
        }
        let start = j;
        while j < n && is_ident(code[j]) {
            j += 1;
        }
        if j == start {
            i += 2;
            continue;
        }
        let name: String = code[start..j].iter().collect();
        let mut depth = 0i32;
        let mut open = None;
        while j < n {
            match code[j] {
                '(' | '[' => depth += 1,
                ')' | ']' => depth -= 1,
                '{' if depth == 0 => {
                    open = Some(j);
                    break;
                }
                ';' if depth == 0 => break,
                _ => {}
            }
            j += 1;
        }
        if let Some(open) = open {
            out.push(FnBody {
                name,
                open,
                close: matching_brace(code, open),
            });
        }
        i = start;
    }
    out
}

/// Lines `from..=to` (0-based) of blanked code that hold anything but whitespace.
pub fn code_lines(code: &[char], starts: &[usize], from: usize, to: usize) -> usize {
    (from..=to)
        .filter(|&l| {
            let a = starts[l];
            let b = starts.get(l + 1).copied().unwrap_or(code.len());
            code[a..b].iter().any(|c| !c.is_whitespace())
        })
        .count()
}

/// The `"key" = N` rows of a metrics table; `#` starts a comment (keys hold no `#` other than
/// an ordinal suffix, which sits inside the quotes).
pub fn parse_table(table: &str, text: &str) -> BTreeMap<String, usize> {
    let mut caps = BTreeMap::new();
    for (n, line) in text.lines().enumerate() {
        let line = line.trim();
        if line.is_empty() || line.starts_with('#') {
            continue;
        }
        let (key, rest) = line
            .rsplit_once('=')
            .unwrap_or_else(|| panic!("{table}:{}: expected \"key\" = N", n + 1));
        let key = key.trim().trim_matches('"').to_string();
        let cap = rest
            .split('#')
            .next()
            .unwrap()
            .trim()
            .parse()
            .unwrap_or_else(|_| panic!("{table}:{}: the cap is not a number", n + 1));
        assert!(
            caps.insert(key.clone(), cap).is_none(),
            "{table}:{}: {key} is listed twice",
            n + 1
        );
    }
    caps
}
